const sleep=ms=>new Promise(r=>setTimeout(r,ms));
window.__state=()=>{const vals=[...document.querySelectorAll('input')].map(i=>i.value).filter(v=>v&&v!=='on');const t=document.body.innerText;const pills=[...document.querySelectorAll('.mantine-Pill-label,[class*=Pill-label]')].map(p=>p.textContent);const i=t.indexOf('Rank');return {vals,pills,first:t.slice(i,i+200).replace(/\n+/g,'|')};};
window.__pick=async(name)=>{const input=[...document.querySelectorAll('input')].find(i=>/Player Traits|Advanced Stats/.test(i.value));input.click();await sleep(600);const opt=[...document.querySelectorAll('[role=option]')].find(o=>o.textContent.trim()===name);if(!opt)return 'no option '+name;opt.dispatchEvent(new MouseEvent('mousedown',{bubbles:true}));opt.click();await sleep(7000);return window.__state();};
window.__download=async()=>{const cols=[...document.querySelectorAll('button')].find(b=>b.textContent.trim()==='Columns');const btn=cols.nextElementSibling||cols.parentElement.nextElementSibling;btn.click();await sleep(700);const item=[...document.querySelectorAll('[role=menuitem],button,a')].find(e=>e.textContent.trim()==='Download CSV');if(!item)return 'no download item';item.click();await sleep(1500);return 'clicked';};
window.__state()

